"""订单：把商品明细算成订单总价。

订单总价 = 商品小计 → 判定是否满足折扣门槛 → 打折扣 → 得到最终金额。
"""

from .pricing import apply_discount, is_discount_eligible


class Order:
    """一个订单。

    :param order_id: 订单号
    :param items: ``[(数量, 单价（分）), ...]``
    :param discount_rate: 折扣率，0 表示不打折
    """

    def __init__(self, order_id: str, items, discount_rate: float = 0.0) -> None:
        self.order_id = order_id
        self.items = list(items)
        self.discount_rate = discount_rate

    def subtotal_cents(self) -> int:
        """商品小计（单位：分）。"""
        return sum(quantity * unit_price for quantity, unit_price in self.items)

    def total_cents(self) -> int:
        """订单最终金额（单位：分）。"""
        subtotal = self.subtotal_cents()
        if not is_discount_eligible(subtotal) or not self.discount_rate:
            return subtotal
        return apply_discount(subtotal, self.discount_rate)

"""订单模块的单元测试。"""

import unittest

from app.order import Order


class OrderTest(unittest.TestCase):
    def test_subtotal(self):
        order = Order("O-1", [(2, 500), (1, 300)])
        self.assertEqual(order.subtotal_cents(), 1300)

    def test_total_rounds_to_cent(self):
        # 10001 分（小计已过 100 元门槛）打 85 折，订单总价应为 8501 分
        order = Order("O-2", [(1, 10001)], discount_rate=0.15)
        self.assertEqual(order.total_cents(), 8501)

    def test_no_discount_below_threshold(self):
        order = Order("O-3", [(1, 500)], discount_rate=0.15)
        self.assertEqual(order.total_cents(), 500)


if __name__ == "__main__":
    unittest.main()

"""定价模块的单元测试。"""

import unittest

from app.pricing import apply_discount, is_discount_eligible


class PricingTest(unittest.TestCase):
    def test_discount_rounds_to_cent(self):
        # 1001 分打 85 折 = 850.85 分，四舍五入应为 851 分
        self.assertEqual(apply_discount(1001, 0.15), 851)

    def test_discount_no_change(self):
        self.assertEqual(apply_discount(1000, 0.0), 1000)

    def test_eligibility_threshold(self):
        self.assertTrue(is_discount_eligible(10000))
        self.assertFalse(is_discount_eligible(9999))


if __name__ == "__main__":
    unittest.main()

